#!/usr/bin/env bash
# wt_dirty_count: gitignored BUILD OUTPUT is junk, a gitignored hand-made file is not.
# 2026-11-14: ebda-store's gitignored apps/docs/.generated/ (regenerated by the docs build, removed by `npm run clean`) made every
# merged ebda-store worktree count as "1 uncommitted file", so the hygiene sweep kept 65 of them (~2.6 GB each) and the disk
# fell below the 30 GB worktree floor. Every case has its NEGATIVE (the old junk pattern).
# Run: bash os/ops/lib/__tests__/wt-dirty.test.sh
set -uo pipefail
OPS="$(cd "$(dirname "$0")/../.." && pwd)"
. "$OPS/lib/wt-safety.sh"
_pass=0; _fail=0
ok() { echo "PASS: $1"; _pass=$((_pass+1)); }
no() { echo "FAIL: $1"; _fail=$((_fail+1)); }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
R="$T/repo"; mkdir -p "$R"
git -C "$R" init -q
printf 'apps/docs/.generated/\nnotes.private\n' > "$R/.gitignore"
git -C "$R" add .gitignore; git -C "$R" -c user.email=t@t -c user.name=t commit -qm init
mkdir -p "$R/apps/docs/.generated"; echo '{}' > "$R/apps/docs/.generated/openapi.json"
[ "$(wt_dirty_count "$R")" = "0" ] && ok "a gitignored .generated/ build output is junk (count 0)" || no "a .generated/ build output counted as dirty"
OLD_RE='(^|/)(node_modules|dist|build|out|coverage|\.next|\.open-next|\.turbo|\.wrangler|\.vite|\.cache|\.parcel-cache|__pycache__|\.pytest_cache|\.vercel|target|\.tmp|tmp|graphify-out|\.husky/_)(/|$)|(^|/)\.DS_Store$|\.(log|tsbuildinfo|pyc)$|(^|/)\.env(\.[A-Za-z0-9_-]+)?$'
n=$(git -C "$R" status --porcelain --ignored=matching --untracked-files=all | sed -n 's/^!! //p' | grep -Ev "$OLD_RE" | wc -l | tr -d ' ')
[ "$n" = "1" ] && ok "NEGATIVE: the old junk pattern counted .generated/ as a file to lose" || no "old pattern did not reproduce the bug"
echo "mine" > "$R/notes.private"
[ "$(wt_dirty_count "$R")" = "1" ] && ok "a gitignored hand-made file still counts (never deleted silently)" || no "a hand-made ignored file was treated as junk"
echo "wip" > "$R/new.txt"
[ "$(wt_dirty_count "$R")" = "2" ] && ok "an untracked file still counts" || no "untracked file not counted"
echo "wt-dirty: $_pass passed, $_fail failed"; [ "$_fail" = 0 ]
